library(tidyverse)

events   &lt;- read_csv("SCoData_events_v2.0_2025.csv")
members  &lt;- read_csv("SCoData_members_v2.0_2025.csv")
creators &lt;- read_csv("SCoData_book_creators_v2.0_2025.csv")

author_genders &lt;- creators |&gt;
  filter(id != "james-henry-2") |&gt;
  select(sort_name, author_gender = gender)

reader_genders &lt;- members |&gt;
  select(id, reader_gender = gender)

borrows &lt;- events |&gt;
  filter(event_type == "Borrow") |&gt;
  filter(!str_detect(member_ids, ";")) |&gt;
  filter(!str_detect(item_authors, ";")) |&gt;
  select(member_ids, member_names, start_date, item_title, item_authors,
         item_year, borrow_duration_days) |&gt;
  left_join(author_genders, by = c("item_authors" = "sort_name")) |&gt;
  left_join(reader_genders, by = c("member_ids" = "id")) |&gt;
  mutate(year = as.numeric(str_sub(start_date, 1, 4)))
